def effect(ctx, hand_type, scored_cards, played_cards, held_cards, game, joker):
    current_count = len(played_cards)
    prev_count = joker.state.get('prev_count', 0)
    if current_count > prev_count:
        # 计算递增倍率：每多一张额外+1.5x，但最多叠加到4x
        increase = 1.5 * (current_count - prev_count)
        if increase > 4.0:
            increase = 4.0
        ctx.x_mult *= increase
    joker.state['prev_count'] = current_count
